START, END = "__start__", "__end__"


class GraphRecursionError(RuntimeError):
    pass


class StateGraph:
    def __init__(self, reducers=None):
        self.reducers = dict(reducers or {})
        self.nodes = {}
        self.edges = {}
        self.cond = {}

    def add_node(self, name, fn):
        self.nodes[name] = fn
        return self

    def add_edge(self, a, b):
        self.edges[a] = b
        return self

    def add_conditional_edges(self, src, router):
        self.cond[src] = router
        return self

    def set_entry_point(self, name):
        self.edges[START] = name
        return self

    def merge(self, state, update):
        merged = dict(state)
        for key, value in update.items():
            if key in self.reducers and key in merged:
                merged[key] = self.reducers[key](merged[key], value)
            else:
                merged[key] = value
        return merged

    def compile(self, checkpointer=None):
        return CompiledGraph(self, checkpointer)


class CompiledGraph:
    def __init__(self, graph, checkpointer=None):
        self.graph = graph
        self.checkpointer = checkpointer

    def invoke(self, state, config=None, recursion_limit=25):
        thread = None
        if self.checkpointer is not None:
            thread = ((config or {}).get("configurable") or {}).get("thread_id")
            if thread is None:
                raise ValueError("a checkpointer needs config['configurable']['thread_id']")
            current = self.graph.merge(self.checkpointer.get(thread, {}), state)
        else:
            current = dict(state)

        node = self.graph.edges[START]
        steps = 0
        while node != END:
            if steps >= recursion_limit:
                raise GraphRecursionError(
                    f"graph did not reach the end within {recursion_limit} steps")
            steps += 1
            update = self.graph.nodes[node](current)
            current = self.graph.merge(current, update)
            if node in self.graph.cond:
                node = self.graph.cond[node](current)
            else:
                node = self.graph.edges[node]
            if node != END and node not in self.graph.nodes:
                raise ValueError(f"no such node: {node!r}")

        if thread is not None:
            self.checkpointer[thread] = current
        return current
